        '1 [done] (p2) Buy milk',
        '2 [pending] (p1) Write report'
      ]);
    });

    test('--status filters pending and done', () {
      run(['add', 'a']);
      run(['add', 'b']);
      run(['done', '2']);
      expect(run(['list', '--status', 'pending']).stdout.trim(),
          '1 [pending] (p3) a');
      expect(run(['list', '--status', 'done']).stdout.trim(),
          '2 [done] (p3) b');
      expect(run(['list', '--status', 'all']).stdout.trim().split('\n').length,
          2);
    });

    test('--status with no matches prints No notes', () {
      run(['add', 'a']);
      expect(run(['list', '--status', 'done']).stdout.trim(), 'No notes');
    });
  });

  group('done', () {
    test('marks note done and persists', () {
      run(['add', 'a']);
      final r = run(['done', '1']);
      expect(r.exitCode, 0);
      expect(r.stdout.trim(), 'Marked note 1 as done');
      expect((readStore()['notes'] as List)[0]['done'], true);
    });

    test('missing id prints not found and exits 1 without writing', () {
      final r = run(['done', '9']);
      expect(r.exitCode, 1);
      expect(r.stdout.trim(), 'Note 9 not found');
      expect(storeFile.existsSync(), isFalse);
    });
  });

  group('remove', () {
    test('removes note and persists', () {
      run(['add', 'a']);
      run(['add', 'b']);
      final r = run(['remove', '1']);
      expect(r.exitCode, 0);
      expect(r.stdout.trim(), 'Removed note 1');
      final store = readStore();
      expect(store['next_id'], 3);
      expect(store['notes'], [
        {'id': 2, 'title': 'b', 'body': '', 'priority': 3, 'done': false}
      ]);
    });

    test('missing id prints not found and exits 1 without writing', () {
      final r = run(['remove', '5']);
      expect(r.exitCode, 1);
      expect(r.stdout.trim(), 'Note 5 not found');
      expect(storeFile.existsSync(), isFalse);
    });
  });

  group('search', () {
    test('case-insensitive over title and body, ascending id', () {
      run(['add', 'Buy Milk']);
      run(['add', 'Write report', '--body', 'due Friday']);
      run(['done', '2']);
      final r = run(['search', 'REPORT']);
      expect(r.stdout.trim(), '2 [done] (p3) Write report');
      expect(run(['search', 'milk']).stdout.trim(),
          '1 [pending] (p3) Buy Milk');
      expect(run(['search', 'friday']).stdout.trim(),
          '2 [done] (p3) Write report');
    });

    test('no matches prints No notes found', () {
      run(['add', 'a']);
      final r = run(['search', 'zzz']);
      expect(r.exitCode, 0);
      expect(r.stdout.trim(), 'No notes found');
    });
  });

  group('sorted', () {
    test('sorts by priority asc, ties by id asc', () {
      run(['add', 'a', '--priority', '2']);
      run(['add', 'b', '--priority', '1']);
      run(['add', 'c', '--priority', '2']);
      final r = run(['sorted']);
      expect(r.stdout.trim().split('\n'), [
        '2 [pending] (p1) b',
        '1 [pending] (p2) a',
        '3 [pending] (p2) c'
      ]);
    });

    test('empty store prints No notes', () {
      final r = run(['sorted']);
      expect(r.exitCode, 0);
      expect(r.stdout.trim(), 'No notes');
    });
  });

  group('persistence', () {
    test('missing file treated as empty store', () {
      expect(storeFile.existsSync(), isFalse);
      expect(run(['list']).stdout.trim(), 'No notes');
    });

    test('state survives across invocations', () {
      run(['add', 'a', '--priority', '1']);
      run(['done', '1']);
      final r = run(['list']);
      expect(r.stdout.trim(), '1 [done] (p1) a');
    });
  });

  group('store unit', () {
    test('formatNote', () {
      expect(
          formatNote(Note(id: 7, title: 't', priority: 5, done: true)),
          '7 [done] (p5) t');
    });

    test('NotesStore.load empty file defaults', () {
      final f = File('${dir.path}/notes.json');
      final store = NotesStore.load(f);
      expect(store.nextId, 1);
      expect(store.notes, isEmpty);
    });

    test('NotesStore.save/load round trip', () {
      final f = File('${dir.path}/notes.json');
      final store = NotesStore(nextId: 1, notes: []);
      store.add(title: 'x', body: 'b', priority: 2);
      store.save(f);
      final loaded = NotesStore.load(f);
      expect(loaded.nextId, 2);
      expect(loaded.notes.single.title, 'x');
      expect(loaded.notes.single.body, 'b');
      expect(loaded.notes.single.priority, 2);
    });
  });
}

